import{_ as n,o as i,c as t,a2 as o}from"./chunks/framework.7R1OEGYz.js";const r="/docs/images/manual/kwh.png",e="/docs/images/manual/kwh-form.png",m=JSON.parse('{"title":"6. Monitoring kWh Produksi","description":"Stand kWh harian engine, penyulang, dan PS total.","frontmatter":{"title":"6. Monitoring kWh Produksi","description":"Stand kWh harian engine, penyulang, dan PS total."},"headers":[],"relativePath":"monitoring-kwh.md","filePath":"monitoring-kwh.md"}'),l={name:"monitoring-kwh.md"};function s(u,a,g,d,h,p){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="_6-monitoring-kwh-produksi" tabindex="-1">6. Monitoring kWh Produksi <a class="header-anchor" href="#_6-monitoring-kwh-produksi" aria-label="Permalink to &quot;6. Monitoring kWh Produksi&quot;">​</a></h1><p>Stand kWh harian engine, penyulang, dan PS total. <span class="manual-badge">Akses: Lihat Monitoring kWh</span></p><h2 id="filter-tampilan" tabindex="-1">Filter &amp; tampilan <a class="header-anchor" href="#filter-tampilan" aria-label="Permalink to &quot;Filter &amp; tampilan&quot;">​</a></h2><ul><li><strong>Bulan</strong>: pilih bulan yang ingin dilihat.</li><li><strong>Ringkasan bulan</strong>: total produksi engine, total PS, dan jumlah hari yang sudah tercatat.</li><li>Tab <strong>Engine</strong>: stand akhir kWh produksi dan kWh PS per engine, beserta grafik produksi harian.</li><li>Tab <strong>Penyulang</strong>: stand akhir kWh produksi per penyulang.</li><li>Tab <strong>PS Total</strong>: kWh PS dan kWh digital per penyulang; nilai <strong>PS Total</strong> dihitung otomatis.</li></ul><figure class="manual-figure"><p><img src="'+r+'" alt="Monitoring kWh Produksi: ringkasan bulan dan grafik produksi harian per engine."></p><figcaption>Monitoring kWh Produksi: ringkasan bulan dan grafik produksi harian per engine.</figcaption></figure><h2 id="menambah-data-kwh-perlu-izin-input-edit-monitoring-kwh" tabindex="-1">Menambah data kWh <span class="manual-badge">Perlu izin: Input/Edit Monitoring kWh</span> <a class="header-anchor" href="#menambah-data-kwh-perlu-izin-input-edit-monitoring-kwh" aria-label="Permalink to &quot;Menambah data kWh &lt;span class=&quot;manual-badge&quot;&gt;Perlu izin: Input/Edit Monitoring kWh&lt;/span&gt;&quot;">​</a></h2><ol><li>Pilih tab yang sesuai (Engine, Penyulang, atau PS Total).</li><li>Tekan tombol <strong>Tambah Data ...</strong> di kanan atas tabel.</li><li>Isi tanggal dan angka stand meter pada formulir, lalu tekan simpan.</li><li>Kolom <strong>Nama Operator</strong> boleh dikosongkan; aplikasi otomatis memakai nama akun Anda.</li><li>Data baru muncul di tabel. Kolom <strong>Terakhir diubah</strong> mencatat siapa dan kapan data diubah.</li></ol><p><span class="manual-badge">Perlu izin: Input/Edit Monitoring kWh</span></p><figure class="manual-figure"><p><img src="'+e+'" alt="Formulir Tambah Data kWh Engine."></p><figcaption>Formulir Tambah Data kWh Engine.</figcaption></figure><h2 id="mengubah-atau-menghapus-data-perlu-izin-input-edit-monitoring-kwh" tabindex="-1">Mengubah atau menghapus data <span class="manual-badge">Perlu izin: Input/Edit Monitoring kWh</span> <a class="header-anchor" href="#mengubah-atau-menghapus-data-perlu-izin-input-edit-monitoring-kwh" aria-label="Permalink to &quot;Mengubah atau menghapus data &lt;span class=&quot;manual-badge&quot;&gt;Perlu izin: Input/Edit Monitoring kWh&lt;/span&gt;&quot;">​</a></h2><ol><li>Pada kolom <strong>Aksi</strong>, tekan ikon pensil untuk mengubah atau ikon tempat sampah untuk menghapus.</li><li>Untuk hapus, konfirmasi pada dialog yang muncul. Data yang dihapus tidak dapat dikembalikan.</li></ol><div class="info custom-block"><p class="custom-block-title">Catatan</p><p>Produksi harian dihitung dari selisih stand hari ini dengan stand hari sebelumnya. Pastikan stand diisi berurutan setiap hari agar perhitungan benar.</p></div>',12)])])}const c=n(l,[["render",s]]);export{m as __pageData,c as default};
